package com.hau.notification.infrastructure.persistence.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="processed_events")public class ProcessedEventEntity{@Id@Column(name="event_id")private UUID id;@Column(name="event_type",nullable=false,length=100)private String type;@Column(name="processed_at",nullable=false)private Instant at;protected ProcessedEventEntity(){}public ProcessedEventEntity(UUID i,String t,Instant a){id=i;type=t;at=a;}}
